isClient.example:
// A file listed in sharedScripts runs on both sides.
const side = kcds.core.Runtime.isClient ? 'client' : 'server';
console.log(`running on the ${side}`);

isClient.exampleCs:
// A file listed in sharedScripts runs on both sides.
var side = Runtime.IsClient ? "client" : "server";
Log.Info($"running on the {side}");

isServer.example:
const { Runtime, Events } = kcds.core;

if (Runtime.isServer) {
  Events.on('playerReady', (player) => console.info(`${player.nickname} is in`));
}

isServer.exampleCs:
if (Runtime.IsServer)
{
    Events.On("playerReady", (Player player) => Log.Info($"{player.Nickname} is in"));
}
